from pathlib import Path
import json
root=Path(__file__).resolve().parent
feed=(root/'feeds/example.json').read_text('utf8')
html=r'''<!doctype html>
<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>MATCHDAY · Android / Wear UI preview</title>
<style>
:root {font-family:Inter,'Noto Sans KR','Malgun Gothic',system-ui,sans-serif;color:#e9f2fa;background:#eef5fa}*{box-sizing:border-box}body{margin:0}
.page{max-width:1370px;margin:0 auto;padding:32px 23px}.heading{color:#173149;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;margin-bottom:20px}.heading h1{font-size:27px;margin:0}.heading small{display:block;color:#667987;font-size:13px;margin-top:5px}.heading .notice{color:#8e4d16;background:#fff3e4;padding:10px 13px;border-radius:10px;font-size:12px;font-weight:750}
.stage{display:flex;gap:33px;align-items:flex-start;justify-content:center;flex-wrap:wrap}.device{width:395px;min-height:790px;border:8px solid #141b24;border-radius:42px;background:#091521;box-shadow:0 20px 50px #1e375740;overflow:hidden;position:relative}.phone-screen{height:765px;overflow:hidden;position:relative;padding-bottom:62px}.statusbar{height:25px;text-align:left;padding-left:21px;color:#adbbc6;font-size:10px;padding-top:7px}.header{display:flex;align-items:center;justify-content:space-between;padding:14px 15px 7px}.brand{font-size:22px;font-weight:900;letter-spacing:-.6px}.brand span{color:var(--accent)}.round-btn{border:1px solid #31455a;border-radius:16px;padding:6px 9px;background:#152839;color:#b8cfde;font-size:10px;cursor:pointer}
.tabs,.leagues{display:flex;gap:4px;padding:6px 13px}.tabs button,.leagues button{flex:1;border:0;border-radius:10px;background:#182a3a;color:#b8c8d5;padding:10px 5px;font-size:12px;cursor:pointer;min-width:0;white-space:nowrap}.tabs button.active,.leagues button.active{background:var(--accent);color:#fff;font-weight:800}.leagues{overflow:auto}.leagues button{font-size:10px;flex:0 0 auto;padding:9px 13px;border:1px solid #253a4b}
.body{padding:9px 14px 17px;height:594px;overflow-y:auto;scrollbar-width:thin;scrollbar-color:#344759 transparent}.demo{font-size:9px;background:#5f371c;color:#ffd9a7;border-radius:7px;padding:7px 8px;margin-bottom:11px;text-align:center}.h2{font-size:18px;font-weight:800;letter-spacing:-.6px;margin:11px 0 10px}.sub{font-size:11px;color:#adbac7;margin:-3px 0 10px}.section{font-size:13px;font-weight:800;margin:16px 0 9px;display:flex;justify-content:space-between}.section span{font-size:10px;color:var(--accent)}
.hero{background:linear-gradient(125deg,var(--accent-dark),#132a3a 55%,#0c1b2b);border:1px solid var(--accent);border-radius:19px;padding:15px 13px;margin-bottom:5px}.hero .small{font-size:12px;color:#d7e6f1;font-weight:700}.teams{display:flex;align-items:center;justify-content:space-between;gap:4px}.team{display:flex;flex-direction:column;align-items:center;gap:5px;flex:1;font-size:12px;font-weight:800}.logo{object-fit:contain;width:32px;height:32px;flex:none}.logo.big{width:63px;height:63px}.score{text-align:center;flex:1;font-weight:900;font-size:26px;white-space:nowrap}.status{padding:4px 7px;border-radius:6px;background:#28435c;color:#b7d3e8;font-size:9px;display:inline-block;font-weight:800}.status.live{background:#672b3e;color:#ff6f76}.status.up{background:#153f45;color:#7ce3c8}.game{border:1px solid #233849;background:#152939;border-radius:13px;padding:9px;margin:7px 0}.gameheader{display:flex;justify-content:space-between;align-items:center;color:#91a8b8;font-size:9px;margin-bottom:7px}.game .teams .logo{width:24px;height:24px}.game .teams{gap:3px}.game .score{font-size:14px}.game .team{font-size:10px;flex-direction:row;justify-content:center}.game small{color:#9fb1bd;font-size:9px;display:block;margin-top:5px;text-align:center}
.standing{display:flex;align-items:center;gap:5px;border-bottom:1px solid #2b4150;padding:8px 6px;font-size:11px}.standing:last-child{border:0}.standing .rank{width:20px;color:#aac2d4}.standing .name{flex:1;font-weight:750}.standing .record{width:76px;text-align:right;color:#dbe7ee}.standing .rate{width:38px;text-align:right;font-weight:800}.standing.fav{background:var(--accent-dark);border-radius:9px}.empty{padding:15px;background:#172b38;border-radius:12px;color:#bdcad7;font-size:12px}
.bracket{display:flex;gap:9px;overflow-x:auto;padding:4px 2px 10px;scrollbar-color:#344759 transparent}.round{width:230px;flex:0 0 230px}.roundhead{font-size:12px;font-weight:800;color:var(--accent);margin:9px 0 9px}.series{border:1px solid #3a5967;background:#172b3c;border-radius:14px;padding:11px;margin-bottom:9px;cursor:pointer}.series.active{border:2px solid var(--accent);background:var(--accent-dark)}.series .r{display:flex;align-items:center;gap:8px;font-size:12px;margin-top:9px}.series .r .logo{width:27px;height:27px}.series .r .sname{flex:1;font-weight:600}.series .r strong{color:var(--accent)}.series small{font-size:9px;color:#9db1be}.detail{background:#192f40;padding:13px;border-radius:14px;margin-top:12px}.detail .line{display:flex;justify-content:space-between;border-bottom:1px solid #30475a;padding:7px 0;font-size:11px}.date-buttons{display:flex;gap:4px;margin:8px 0;overflow:auto}.date-buttons button{color:#dceaf3;border:1px solid #2b4655;background:#172c40;border-radius:10px;padding:7px 9px;white-space:nowrap;cursor:pointer}.date-buttons button.active{background:var(--accent)}
.bottom{position:absolute;bottom:0;left:0;right:0;height:61px;background:#07131f;border-top:1px solid #23384a;display:flex;justify-content:space-around;align-items:center}.bottom button{background:none;color:#b6c9d9;border:none;font-size:11px;cursor:pointer}.bottom button.active{color:var(--accent);font-weight:800}.bottom i{display:block;font-size:21px;font-style:normal;margin-bottom:2px}
.watchpanel{width:250px;margin-top:26px}.watchpanel h2{font-size:14px;color:#244057;text-align:center;margin:0 0 18px}.watch{width:235px;height:235px;border:11px solid #181c23;border-radius:50%;background:#0b1b28;box-shadow:0 13px 26px #16395455;padding:20px 12px;overflow:hidden;text-align:center}.watch+.watch{margin-top:20px}.watch-title{font-size:13px;font-weight:800}.watch-head{font-size:10px;color:#a4bbcd;padding:10px 0}.watch-teams{display:flex;gap:3px;justify-content:space-between;align-items:center}.watch-teams div{flex:1;text-align:center;font-size:9px}.watch-teams img{width:43px;height:43px;display:block;margin:auto}.watch-score{font-size:20px;font-weight:900;white-space:nowrap}.watch .status{margin-top:6px}.watch sub{font-size:9px;display:block;margin-top:9px;color:#ffd39b}
.controls{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.controls button{background:white;color:#2c4560;padding:9px 15px;border:1px solid #d4e0ed;border-radius:10px;cursor:pointer;font-weight:700}.controls button.selected{background:#153550;color:#fff}.explainer{margin-top:28px;background:#fff;color:#21364b;padding:18px 22px;border-radius:14px;line-height:1.6;font-size:13px}.explainer b{color:#1b5392}@media(max-width:850px){.device{margin:auto}.stage{gap:22px}}
</style>
</head><body><main class="page">
<div class="heading"><div><h1>MATCHDAY | Android Studio UI 프리뷰</h1><small>폰 · 워치 · KBO · LCK/MSI/EWC/롤드컵 · 일정/대진/순위 화면 구조</small></div><div class="notice">데모 가상 기록 · 실제 경기/실시간 데이터 아님</div></div>
<div class="controls"><button onclick="setSport('KBO')" id="kboButton" class="selected">KBO · 삼성</button><button onclick="setSport('LOL')" id="lolButton">LoL · Gen.G</button><button onclick="setTab('오늘')">오늘</button><button onclick="setTab('일정')">일정</button><button onclick="setTab('대진')">대진</button><button onclick="setTab('순위')">순위</button></div>
<div class="stage"><div class="device"><div class="phone-screen"><div class="statusbar">11:45 ◆ ▴ ◕</div><div class="header"><div class="brand">MATCH<span>DAY</span></div><div class="round-btn">⚙ 기기 설정</div></div><div class="tabs" id="tabs"></div><div class="leagues" id="leagues"></div><div class="body" id="body"></div><div class="bottom" id="bottom"></div></div></div>
<div class="watchpanel"><h2>갤럭시 워치 타일 2종</h2><div class="watch" id="wkbo"></div><div class="watch" id="wlol"></div></div></div>
<div class="explainer"><b>동작 방식:</b> 위쪽 종목·화면 버튼을 눌러 화면을 바꿀 수 있습니다. 폰의 대진표는 가로로 스크롤하며 시리즈를 클릭하면 개별 경기 결과를 볼 수 있습니다. 워치 앱에서는 동일한 데이터를 작은 화면에 맞게 세로 카드로 제공합니다. 이 HTML은 Android 앱 자체가 아닌 <b>레이아웃을 검토하기 위한 브라우저용 UI 미리보기</b>입니다.</div>
</main><script id="feed" type="application/json">__DATA__</script><script>
const feed=JSON.parse(document.getElementById('feed').textContent);
const teams=Object.fromEntries(feed.teams.map(t=>[t.id,t]));let sport='KBO', compLol='LCK', tab='오늘', d='2026-10-30', selectedSeries='';
function comp(){return sport==='KBO'?'KBO':compLol}function lab(c){return c==='WORLDS'?'롤드컵':c}
function logo(id,cls=''){return teams[id]?`<img class="logo ${cls}" src="../phone/src/main/res/drawable-nodpi/team_${id.toLowerCase()}.png" alt="${teams[id].name}">`:'<span>?</span>'}
function name(id){return (teams[id]||{short:'미정'}).short}function status(x){return `<span class="status ${x==='LIVE'?'live':x==='UPCOMING'?'up':''}">${{LIVE:'LIVE',UPCOMING:'예정',FINAL:'종료',POSTPONED:'연기'}[x]||x}</span>`}
function game(g){return `<div class="game"><div class="gameheader"><span>${g.stage||g.competition} · ${g.dateTime.slice(0,10)}</span>${status(g.status)}</div><div class="teams"><div class="team">${logo(g.home)}${name(g.home)}</div><div class="score">${g.homeScore===null?g.dateTime.slice(11,16):g.homeScore+' : '+g.awayScore}</div><div class="team">${name(g.away)}${logo(g.away)}</div></div><small>${g.venue}</small></div>`}
function standings(max=20){return feed.standings.filter(s=>s.competition===comp()).sort((a,b)=>a.rank-b.rank).slice(0,max).map(s=>`<div class="standing ${s.team===(sport==='KBO'?'SAM':'GEN')?'fav':''}"><span class="rank">${s.rank}</span>${logo(s.team)}<span class="name">${name(s.team)}</span><span class="record">${s.won}승 ${s.lost}패</span><span class="rate">${sport==='KBO'?(s.won/(s.won+s.lost)).toFixed(3):'+'+(s.forScore-s.againstScore)}</span></div>`).join('')||'<div class="empty">순위 정보 없음</div>'}
function series(x){return `<div class="series ${selectedSeries===x.id?'active':''}" onclick="selectedSeries='${x.id}'; render()"><div style="display:flex;justify-content:space-between;align-items:center"><small>${x.stage}</small>${status(x.status)}</div><div class="r">${logo(x.left)}<span class="sname">${name(x.left)}</span><strong>${x.status==='UPCOMING'?'–':x.leftWins}</strong></div><div class="r">${logo(x.right)}<span class="sname">${name(x.right)}</span><strong>${x.status==='UPCOMING'?'–':x.rightWins}</strong></div><small>Bo${x.bestOf} · ${x.scheduled.slice(0,16).replace('T',' ')}</small></div>`}
function render(){let c=comp();document.documentElement.style.setProperty('--accent',sport==='KBO'?'#438bff':'#14bd7a');document.documentElement.style.setProperty('--accent-dark',sport==='KBO'?'#16477a':'#0b5a46');
document.getElementById('kboButton').className=sport==='KBO'?'selected':'';document.getElementById('lolButton').className=sport==='LOL'?'selected':'';
document.getElementById('tabs').innerHTML=['오늘','일정','대진','순위'].map(t=>`<button class="${tab===t?'active':''}" onclick="setTab('${t}')">${t}</button>`).join('');
document.getElementById('bottom').innerHTML=['오늘','일정','대진','순위'].map((t,i)=>`<button onclick="setTab('${t}')" class="${tab===t?'active':''}"><i>${['⌂','▦','⌘','▤'][i]}</i>${t}</button>`).join('');
document.getElementById('leagues').innerHTML=sport==='LOL'?['LCK','MSI','EWC','WORLDS','FST'].map(x=>`<button class="${compLol===x?'active':''}" onclick="setComp('${x}')">${lab(x)}</button>`).join(''):'';
let matches=feed.games.filter(g=>g.competition===c);let res=`<div class="demo">DEMO · 가상 일정·점수·순위 · 실제 경기 아님</div>`;
if(tab==='오늘'){let f=matches.find(g=>(g.home===(sport==='KBO'?'SAM':'GEN')||g.away===(sport==='KBO'?'SAM':'GEN'))&&g.dateTime.startsWith(d))||matches[0];res+=`<div class="h2">${lab(c)} · 오늘 경기</div><div class="hero"><div class="small">★ MY TEAM · ${sport==='KBO'?'삼성 라이온즈':'Gen.G'}</div><div class="sub">${f.stage} · ${f.dateTime.slice(0,10)}</div><div class="teams"><div class="team">${logo(f.home,'big')}${name(f.home)}</div><div class="score">${f.homeScore===null?f.dateTime.slice(11,16):f.homeScore+' : '+f.awayScore}<br>${status(f.status)}</div><div class="team">${logo(f.away,'big')}${name(f.away)}</div></div><div class="sub" style="text-align:center;margin-top:12px">${f.venue}</div></div><div class="section">오늘의 전체 경기 <span>${matches.filter(g=>g.dateTime.startsWith(d)).length}경기</span></div>${matches.filter(g=>g.dateTime.startsWith(d)).map(game).join('')}<div class="section">순위 미리보기 <span onclick="setTab('순위')">전체 보기 ›</span></div>${standings(4)}`}
if(tab==='순위')res+=`<div class="h2">${lab(c)} 순위표</div><p class="sub">2026 데모 · 삼성/Gen.G 강조</p>${standings()}`;
if(tab==='일정')res+=`<div class="h2">${lab(c)} 경기 일정</div><div class="date-buttons">${['2026-10-29','2026-10-30','2026-10-31','2026-11-03','2026-11-05'].map(x=>`<button class="${x===d?'active':''}" onclick="d='${x}';render()">${x.slice(5)}</button>`).join('')}</div><div class="section">${d} 일정</div>${matches.filter(g=>g.dateTime.startsWith(d)).map(game).join('')||'<div class="empty">해당 날짜 경기가 없습니다</div>'}<div class="section">다가오는 경기</div>${matches.filter(g=>g.dateTime.slice(0,10)>d).slice(0,4).map(game).join('')}`;
if(tab==='대진'){let nodes=feed.series.filter(x=>x.competition===c);let groups=[...new Set(nodes.map(x=>x.group))];let activeGroup=window.g|| (groups.includes('UPPER')?'UPPER':'MAIN');if(!groups.includes(activeGroup))activeGroup=groups.includes('UPPER')?'UPPER':'MAIN';let filtered=nodes.filter(x=>x.group===activeGroup);let rounds=[...new Set(filtered.map(x=>x.roundIndex))].sort((a,b)=>a-b);let detail=nodes.find(x=>x.id===selectedSeries)||filtered[0];res+=`<div class="h2">${sport==='KBO'?'가을야구':lab(c)+' 토너먼트'} 대진표</div><div class="sub">← 가로 스크롤 → · 라운드/시리즈 선택</div>`;if(groups.length>1)res+=`<div class="date-buttons">${groups.map(x=>`<button class="${x===activeGroup?'active':''}" onclick="window.g='${x}';selectedSeries='';render()">${{UPPER:'승자조',LOWER:'패자조',MAIN:'결승'}[x]||x}</button>`).join('')}</div>`;res+=`<div class="bracket">${rounds.map(r=>`<div class="round"><div class="roundhead">${filtered.find(x=>x.roundIndex===r).stage} →</div>${filtered.filter(x=>x.roundIndex===r).map(series).join('')}</div>`).join('')}</div>`;if(detail){let gs=feed.games.filter(x=>x.seriesId===detail.id);res+=`<div class="section">선택한 시리즈 · ${detail.stage}</div><div class="detail"><div style="font-weight:800;margin-bottom:7px">${name(detail.left)} ${detail.leftWins} : ${detail.rightWins} ${name(detail.right)}</div>${gs.length?gs.map(g=>`<div class="line"><span>${g.dateTime.slice(5,16).replace('T',' ')}</span><span>${name(g.home)} ${g.homeScore===null?'VS':g.homeScore+'-'+g.awayScore} ${name(g.away)}</span></div>`).join(''):'<small>세부 경기 결과 등록 전</small>'}</div>`}}
document.getElementById('body').innerHTML=res;watchTile('KBO','wkbo','#368dff');watchTile('LOL','wlol','#20c478')}
function watchTile(sport,id,color){let comps=sport==='KBO'?['KBO']:['LCK','MSI','EWC','WORLDS'];let fav=sport==='KBO'?'SAM':'GEN';let match=feed.games.find(x=>comps.includes(x.competition)&&x.dateTime.startsWith(d)&&(x.home===fav||x.away===fav))||feed.games.find(x=>comps.includes(x.competition)&&(x.home===fav||x.away===fav));let el=document.getElementById(id);el.style.borderColor=color;el.innerHTML=`<div class="watch-title" style="color:${color}">${sport==='KBO'?'⚾ KBO':'◇ LoL'}</div><div class="watch-head">${match?match.dateTime.slice(0,10):'오늘 경기가 없습니다'}</div><div class="watch-teams"><div>${logo(match.home)}${name(match.home)}</div><span class="watch-score">${match.homeScore===null?match.dateTime.slice(11,16):match.homeScore+':'+match.awayScore}</span><div>${logo(match.away)}${name(match.away)}</div></div>${status(match.status)}<sub>데모 · 실제 경기 아님</sub>`}
function setSport(x){sport=x;selectedSeries='';window.g=null;render()}function setComp(x){compLol=x;selectedSeries='';window.g=null;render()}function setTab(x){tab=x;selectedSeries='';render()}render();
</script></body></html>'''
html=html.replace('__DATA__',feed.replace('</','<\\/'))
out=root/'previews/index.html';out.write_text(html,encoding='utf8')
print('preview created',out,len(html))
